// variant of "Little Fibonacci Sphere" by Xor. https://shadertoy.com/view/7tVSDh

void mainImage( out vec4 O, vec2 u)
{
    vec2 R = iResolution.xy, p,
         U = ( u+u - R ) / R.y;
    O*=0.;    

    for(float i=-1.; i<1.; i+=6e-3)
    {
        p = cos(i*4e2+iTime+vec2(0,11))*sqrt(1.-i*i);    // Fibonacci distrib + Rotate
        vec3 h = 2.*fract(1e4*sin(i*vec3(1733,-7117,2913)))-1.; // 3D rand
        h.xz *= cos(i*4e2+iTime+vec2(0,11));
        h = mix( h, vec3(p.x,i,p.y), .9+.1*sin(iTime) ); // interpolate between both points
        O += smoothstep(3./R.y,0.,length(U-h.xy/(h.z+2.))-.01/(h.z+2.)); // perspective + draw point
    }
}
